/* empty css                                                                               */import{H as e}from"./chunks/HighLightText.DA6OcS8b.js";import{c as l,o as i,d as t,a as s,b as p,e as a,w as o}from"./chunks/vitepress-theme-teek.CQIWG8wh.js";/* empty css                                                             */const r={class:"tip custom-block"},h=JSON.parse('{"title":"Token（词元）：LLM 文本处理的最小单元","description":"从 Token 定义出发，详解 BPE、WordPiece 等四种主流子词分词算法原理，分析词表大小对模型效率与 API 成本的三重影响，并阐明 Token 与上下文窗口容量的换算关系，为 LLM 选型与成本优化提供基础认知。","frontmatter":{"date":"2026-06-28T15:51:48.000Z","title":"Token（词元）：LLM 文本处理的最小单元","aliases":["词元"],"tldr":"Token 是 LLM 的计费单位与上下文容量标尺——词表大小、分词算法和 API 成本都围绕它运转。","description":"从 Token 定义出发，详解 BPE、WordPiece 等四种主流子词分词算法原理，分析词表大小对模型效率与 API 成本的三重影响，并阐明 Token 与上下文窗口容量的换算关系，为 LLM 选型与成本优化提供基础认知。","tags":["概念","LLM","Token","分词","Bpe"],"categories":["大模型基础","核心概念"],"permalink":"/llm-basic/token-concept"},"headers":[],"relativePath":"llm-basic/token-concept.md","filePath":"22.大模型基础/02.核心概念/02.Token.md"}'),u={name:"llm-basic/token-concept.md"},g=Object.assign(u,{setup(d){return(b,n)=>(i(),l("div",null,[n[7]||(n[7]=t(`<h1 id="token-词元-llm-文本处理的最小单元" tabindex="-1">Token（词元）：LLM 文本处理的最小单元 <a class="header-anchor" href="#token-词元-llm-文本处理的最小单元" aria-label="Permalink to “Token（词元）：LLM 文本处理的最小单元”">​</a></h1><blockquote><p><strong>摘要</strong>: Token（词元）是 LLM 处理文本的最小语义单元，也是贯穿模型效率、API 计费与上下文容量管理的核心概念。本文从 Token 的基本定义与分词的必要性出发，系统对比了 BPE、WordPiece、SentencePiece 和 Unigram 四种主流子词分词算法——重点解剖了使用最广泛的 BPE 算法的逐级合并过程——进而分析了词表大小在 Embedding 参数量、中文编码效率与 API 调用成本之间的三重权衡。最后，本文建立了 Token 与上下文窗口之间的换算关系，阐明在选型时同时评估窗口大小和 tokenizer 词表效率的必要性。全文为理解 LLM 的文本处理流水线提供了从 Token 视角出发的完整认知地图。</p></blockquote><h2 id="_1-token-的定义" tabindex="-1">1. Token 的定义 <a class="header-anchor" href="#_1-token-的定义" aria-label="Permalink to “1. Token 的定义”">​</a></h2><p><strong>Token（词元）</strong> 是 LLM 处理文本的<strong>最小单位</strong>。模型不直接&quot;阅读&quot;人类文字，而是先将文本切分成一段段 token，每个 token 对应词表中的一个整数 ID。</p><p>为什么叫&quot;词元&quot;而不是&quot;词&quot;？因为一个 token 不总是一个完整的词。以 GPT-4 的标准 tokenizer 为例：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>中文句子:  &quot;人工智能改变世界&quot;</span></span>
<span class="line"><span>  → tokens: [&quot;人工&quot;, &quot;智能&quot;, &quot;改变&quot;, &quot;世界&quot;]          (1 个中文汉字 ≈ 1-2 tokens)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>英文句子:  &quot;Artificial intelligence changes the world&quot;</span></span>
<span class="line"><span>  → tokens: [&quot;Art&quot;, &quot;ificial&quot;, &quot; intelligence&quot;, &quot; changes&quot;, &quot; the&quot;, &quot; world&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>混合:      &quot;Transformer 是一种神经网络架构&quot;</span></span>
<span class="line"><span>  → tokens: [&quot;Transformer&quot;, &quot; 是一种&quot;, &quot;神经网络&quot;, &quot;架构&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div>`,6)),s("div",r,[n[1]||(n[1]=s("p",{class:"custom-block-title"},"为什么需要 tokenization？",-1)),p(e,{bold:""},{default:o(()=>[...n[0]||(n[0]=[a("因为 GPU 只能做数值运算，Tokenizer 将文字序列转化为整数向量 ",-1)])]),_:1}),n[2]||(n[2]=a("[10449, 43290, 33490, ...]，然后 ",-1)),n[3]||(n[3]=s("strong",null,"Embedding 层再将整数映射为 GPU 能计算的浮点向量",-1)),n[4]||(n[4]=a("。",-1)),n[5]||(n[5]=s("p",null,'Tokenizer 是整个 LLM 流水线中的"翻译官"——它架起了人类语言与数学世界之间的桥梁。',-1))]),n[8]||(n[8]=t(`<h2 id="_2-tokenization-分词算法" tabindex="-1">2. Tokenization 分词算法 <a class="header-anchor" href="#_2-tokenization-分词算法" aria-label="Permalink to “2. Tokenization 分词算法”">​</a></h2><p>将文字拆成 token 并非简单按空格或字符切分。现代 LLM 使用<strong>子词分词算法（Subword Tokenization）</strong>，在&quot;词&quot;和&quot;字符&quot;之间寻找平衡点：既能用少量 token 表示常见词，又能用字符拼接表示生僻词。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>全词分词的问题：      &quot;running&quot; 和 &quot;runner&quot; 是两个完全不同的 token，</span></span>
<span class="line"><span>                     模型学不到它们共享 &quot;run&quot; 词根 → 词表膨胀，泛化性差</span></span>
<span class="line"><span></span></span>
<span class="line"><span>字符分词的问题：      &quot;transformer&quot; → t-r-a-n-s-f-o-r-m-e-r（13 个字符 token）</span></span>
<span class="line"><span>                     序列过长，语义被割裂，训练和推理效率都低</span></span>
<span class="line"><span></span></span>
<span class="line"><span>子词分词（最优）：    &quot;transformer&quot; → [&quot;trans&quot;, &quot;former&quot;]（2 个子词 token）</span></span>
<span class="line"><span>                     &quot;running&quot;    → [&quot;runn&quot;, &quot;ing&quot;]</span></span>
<span class="line"><span>                     保留词根共性能，同时词表可控</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>四种主流子词算法对比：</strong></p><table tabindex="0"><thead><tr><th>算法</th><th>代表 Tokenizer</th><th>切分方向</th><th>核心思想</th></tr></thead><tbody><tr><td><strong>BPE</strong>（Byte Pair Encoding）</td><td>GPT 全系列、Llama</td><td>自底向上（合并）</td><td>从字符出发，反复合并高频相邻对</td></tr><tr><td><strong>WordPiece</strong></td><td>BERT</td><td>自底向上</td><td>类似 BPE，但用概率增益而非频率选择合并</td></tr><tr><td><strong>SentencePiece</strong></td><td>T5、LLaMA 2</td><td>自底向上</td><td>BPE 或 Unigram，直接处理原始文本（不依赖空格预分割）</td></tr><tr><td><strong>Unigram</strong></td><td>XLNet、ALBERT</td><td>自顶向下（剪枝）</td><td>先假设一个巨大词表，逐步删除&quot;贡献小&quot;的子词</td></tr></tbody></table><p><strong>BPE 分词过程图解（最广泛使用的算法）：</strong></p><div class="note custom-block github-alert"><p class="custom-block-title">常见词保持完整</p><p></p><p>生僻词与新词，可自动拆为子词组合（如 &quot;unalienable&quot; → [&quot;un&quot;, &quot;alien&quot;, &quot;able&quot;]）</p></div><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>示例: &quot;lower low&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 1: 字符级初始化</span></span>
<span class="line"><span>        [&quot;l&quot;, &quot;o&quot;, &quot;w&quot;, &quot;e&quot;, &quot;r&quot;, &quot; &quot;, &quot;l&quot;, &quot;o&quot;, &quot;w&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 2~4: 反复合并最高频相邻对</span></span>
<span class="line"><span>        高频对 &quot;l&quot; + &quot;o&quot; → &quot;lo&quot;</span></span>
<span class="line"><span>        高频对 &quot;lo&quot; + &quot;w&quot; → &quot;low&quot;</span></span>
<span class="line"><span>        高频对 &quot;e&quot; + &quot;r&quot; → &quot;er&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终:   [&quot;low&quot;, &quot;er&quot;, &quot; &quot;, &quot;low&quot;]</span></span>
<span class="line"><span>        ↑ 两个 &quot;low&quot; 共享子词，一个 &quot;er&quot; 服务于 lower/wider/deeper 等</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BPE 的巧妙之处：常见词保持完整（如 &quot;the&quot; → 1 token），</span></span>
<span class="line"><span>              生僻词/新词自动拆为子词组合（如 &quot;unalienable&quot; → [&quot;un&quot;, &quot;alien&quot;, &quot;able&quot;]）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="_3-tokenizer-与词表大小" tabindex="-1">3. Tokenizer 与词表大小 <a class="header-anchor" href="#_3-tokenizer-与词表大小" aria-label="Permalink to “3. Tokenizer 与词表大小”">​</a></h2><p>每个 LLM 都有一个固定大小的<strong>词表（Vocabulary）</strong>，其中每个 token 对应一个唯一的整数 ID。词表大小直接影响模型效率：</p><table tabindex="0"><thead><tr><th>模型</th><th>词表大小</th><th>说明</th></tr></thead><tbody><tr><td>GPT-2/3/4</td><td>50,257 ~ 100,000</td><td><strong>英文为主，中文效率偏低</strong></td></tr><tr><td>Llama 2/3</td><td>32,000</td><td>相对小，clean 文本</td></tr><tr><td>Qwen 2.5</td><td>152,064</td><td>多语言大词表，中文 1 汉字约 1 token</td></tr><tr><td>DeepSeek-V3</td><td>129,280</td><td>大词表，兼顾中英文效率</td></tr><tr><td>Gemma 2</td><td>256,128</td><td>超大词表，多语言覆盖最广</td></tr></tbody></table><p><strong>词表大小是一把双刃剑：</strong></p><blockquote><p><strong>一个好的 tokenizer 应该</strong>：常见词 1 token、生僻词 2-3 tokens、支持多语言时各语言 token 效率均衡。</p></blockquote><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>词表太大的代价：</span></span>
<span class="line"><span>  Embedding 矩阵 = vocab_size × d_model → 词表每增大 1 万，参数多出数千万</span></span>
<span class="line"><span>  如 DeepSeek-V3: 129280 × 7168 ≈ 9.27 亿参数仅用于 Embedding</span></span>
<span class="line"><span></span></span>
<span class="line"><span>词表太小的代价：</span></span>
<span class="line"><span>  中文文本被过度切碎 → 同样语义需要更多 token → 上下文窗口被快速占满</span></span>
<span class="line"><span>  例如：GPT-3 tokenizer 下，100 字中文 ≈ 200+ tokens，llama-3 约 150 tokens</span></span>
<span class="line"><span>        而在 Qwen tokenizer 下，100 字中文 ≈ 100-120 tokens</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="_4-token-与计费的关系" tabindex="-1">4. Token 与计费的关系 <a class="header-anchor" href="#_4-token-与计费的关系" aria-label="Permalink to “4. Token 与计费的关系”">​</a></h2>`,15)),p(e,{bold:"",type:"note"},{default:o(()=>[...n[6]||(n[6]=[a("所有 LLM API 的计费都基于 token。",-1)])]),_:1}),n[9]||(n[9]=t(` 我们没调用一次模型对话接口，API 提供商会同时计算 input tokens（你的提示）和 output tokens（模型的回复），分别按不同费率收费。<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>一次典型 API 调用的 token 账单（以某模型定价为例）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Input:  用户的 System Prompt（200 tokens）</span></span>
<span class="line"><span>        + 对话历史（800 tokens）</span></span>
<span class="line"><span>        + 用户最新消息（100 tokens）</span></span>
<span class="line"><span>        ──────────────────────────────</span></span>
<span class="line"><span>        = 1,100 input tokens  × ¥0.008/1K = ¥0.0088</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Output: 模型回复（400 tokens）</span></span>
<span class="line"><span>        = 400 output tokens × ¥0.016/1K = ¥0.0064</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总计：约 ¥0.015（1.5 分钱）/ 次对话</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么 output 比 input 贵？</p><p><strong>输出 token 是在推理时逐个生成的（自回归），无法像 input token 那样批量并行计算</strong>。</p><p>此外，每生成一个 output token 都需要计算它之前所有 token 的注意力——生成第 500 个 token 时，需要计算 500×500 的注意力矩阵，计算量随输出长度增长。</p><p><strong>实务建议</strong>：控制 System Prompt 长度、适时裁剪对话历史、用大词表模型处理中文（降低 token 数），都是有效降本手段。</p></div><h2 id="_5-token-与上下文窗口的关系" tabindex="-1">5. Token 与上下文窗口的关系 <a class="header-anchor" href="#_5-token-与上下文窗口的关系" aria-label="Permalink to “5. Token 与上下文窗口的关系”">​</a></h2><p>上下文窗口（Context Window）的容量是用 token 数来衡量的。例如 &quot;128K 上下文窗口&quot; 意味着模型一次最多能处理 128,000 个 token。</p><p><strong>一个直观的换算：</strong></p><table tabindex="0"><thead><tr><th>内容类型</th><th>换算关系</th><th>128K 窗口能容纳</th></tr></thead><tbody><tr><td>英文</td><td>0.75 词 ≈ 1 token</td><td>约 96,000 词，相当于一本 150 页的书</td></tr><tr><td>中文（大词表）</td><td>0.8-1.2 汉字 ≈ 1 token</td><td>约 10-15 万汉字</td></tr><tr><td>中文（小词表）</td><td>1.5-2.5 汉字/1 token</td><td>约 5-8 万汉字（效率大幅下降）</td></tr><tr><td>代码</td><td>约 0.5-1 字符/token</td><td>约 6.5-13 万字符</td></tr></tbody></table><p>因此，选模型时不仅要看窗口大小（128K vs 256K），还要关心 <strong>tokenizer 的词表大小</strong>——同样的中文内容，在 Qwen 的 tokenizer 下占 10K token，在 GPT-3 的 tokenizer 下可能占 20K token，这意味着前者的有效上下文容量是后者的 2 倍。</p>`,8))]))}});export{h as __pageData,g as default};
